	"sampling_results" jsonb,
	"fieldwork_results" jsonb,
	"cleaning_config" jsonb DEFAULT '{"removeSpeeders":true,"removeStraightliners":true,"requirePrimaryTargetValid":true}'::jsonb NOT NULL,
	"diagnostics_summary" jsonb,
	"completed_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "experiment_wave_ck_number" CHECK ("experiment_wave"."wave_number" >= 1),
	CONSTRAINT "experiment_wave_ck_kind" CHECK ("experiment_wave"."kind" in ('pilot', 'main', 'refinement'))
);
